import{_ as t,c,o as s,ak as l}from"./chunks/framework.gmyagHYt.js";const h=JSON.parse('{"title":"基础使用","description":"正确使用ETS2LA","frontmatter":{"title":"基础使用","description":"正确使用ETS2LA","layout":"doc"},"headers":[],"relativePath":"version/v3/docs/base/use.md","filePath":"version/v3/docs/base/use.md"}'),n={name:"version/v3/docs/base/use.md"};function e(o,a,r,g,i,d){return s(),c("div",null,[...a[0]||(a[0]=[l('<h1 id="基础使用" tabindex="-1">基础使用 <a class="header-anchor" href="#基础使用" aria-label="Permalink to “基础使用”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>1.目前对于A卡可能会无法渲染路径线的问题 这不是你的问题 需耐心等待作者修复即可</p></div><h3 id="_1-新手引导" tabindex="-1">1. 新手引导 <a class="header-anchor" href="#_1-新手引导" aria-label="Permalink to “1. 新手引导”">​</a></h3><p>第一次打开软件你看到的界面应该是这样的，左上角的是软件的控制台，显示的是实时日志，屏幕中心显示的是软件主界面。 <img src="https://tuchuang.ets2la.cn/csharp/20260902105022759.png" alt="" loading="lazy"> 软件刚打开会让你选择语言，点击 <code>English - English</code> 位置即可显示下拉框， <img src="https://tuchuang.ets2la.cn/csharp/20260902105357282.png" alt="" loading="lazy"> 在下拉框中选择 <code>简体中文 - Chinese Simplified</code> ，然后点击 <code>restart</code>， <img src="https://tuchuang.ets2la.cn/csharp/20260902105535637.png" alt="" loading="lazy"> 软件会重启并切换到简体中文，然后点击 <code>下一步</code>。 <img src="https://tuchuang.ets2la.cn/csharp/20260902105738910.png" alt="" loading="lazy"> 软件会自动识别游戏的安装目录，点击 <code>Install SDKs</code> 来安装SDK（<strong>SDK的安装需要在游戏未启动的状态下进行，游戏在运行时安装会导致SDK安装不上</strong>） <img src="https://tuchuang.ets2la.cn/csharp/20260902105919457.png" alt="" loading="lazy"> 只有当SDK安装完成之后才能点击 <code>继续</code><img src="https://tuchuang.ets2la.cn/csharp/20260902105942369.png" alt="" loading="lazy"> 游戏更新之后记得在软件 <code>设置</code> 中重新安装SDK（这是一条提醒），然后点击 <code>我明白</code> 按钮继续引导流程 <img src="https://tuchuang.ets2la.cn/csharp/20260902110042516.png" alt="" loading="lazy"> 软件会告诉你叠加层的概念（实时日志也属于叠加层的一部分），并告诉你如何调整叠加层， <img src="https://tuchuang.ets2la.cn/csharp/20260902110220180.png" alt="" loading="lazy"> 如果你的键盘没有 <strong>右Alt</strong> 键，你需要点击 <code>键盘 按键 RightAlt</code> 部分来修改按键（点击之后需要在5秒内在键盘上有输入，超过5秒则认定为绑定超时） <img src="https://tuchuang.ets2la.cn/csharp/20260902110444333.png" alt="" loading="lazy"> 如果你不需要修改按键则尝试<strong>按住</strong> 右Alt键不松，软件的按键部分会变色进行提示表明功能正常 按住按键之后会在屏幕中间看到 <code>控制台</code> 等字样，点击则可对其进行关闭 <img src="https://tuchuang.ets2la.cn/csharp/20260902110853089.png" alt="" loading="lazy"> 点击继续则继续进行引导流程 <img src="https://tuchuang.ets2la.cn/csharp/20260902110924579.png" alt="" loading="lazy"> 然后会是一些辅助说明，需要详细阅读并进行测试以理解（<strong>这对后面的使用非常重要</strong>） <img src="https://tuchuang.ets2la.cn/csharp/20260902112826365.png" alt="" loading="lazy"> 具体操作方式可以简单理解为</p><ol><li>先使用 ← 键来设置辅助模式</li><li>在选择到想使用的模式之后使用 ↑ 和 ↓ 键来启动（↑ 键不会修改设定的速度，↓ 键会修改设定的速度）</li><li>当速度过快时可使用 ↓ 键来降低速度</li><li>当速度过慢时可使用 ↑ 键来增加速度</li><li>再次按下 ← 键则为 取消辅助 简单总结就是 在辅助 <strong>未启用</strong> 的状态下 ← 键用来控制模式选择，在辅助 <strong>启用</strong> 状态下用来关闭辅助，↑、↓键用来控制速度 理解这部分之后点击<code>继续</code> 接着引导流程 <img src="https://tuchuang.ets2la.cn/csharp/20260902113238822.png" alt="" loading="lazy"> 推荐插件页面建议直接点击 <code>安装插件</code> ，如点击 <code>继续</code> 则后续需要在 <code>插件库</code> 中安装插件 <img src="https://tuchuang.ets2la.cn/csharp/20260902113319985.png" alt="" loading="lazy"> 插件安装完成之后点击重启并继续 <img src="https://tuchuang.ets2la.cn/csharp/20260902113354008.png" alt="" loading="lazy"> 免责声明这边看一下即可，不做过多说明 <img src="https://tuchuang.ets2la.cn/csharp/20260902113512404.png" alt="" loading="lazy"><img src="https://tuchuang.ets2la.cn/csharp/20260902113522437.png" alt="" loading="lazy"> 引导流程结束之后点击<strong>文字</strong>所指位置的点即可打开侧边栏 <img src="https://tuchuang.ets2la.cn/csharp/20260902113543723.png" alt="" loading="lazy"></li></ol><h2 id="_6-更新" tabindex="-1">6. 更新 <a class="header-anchor" href="#_6-更新" aria-label="Permalink to “6. 更新”">​</a></h2><p>由于软件仍在开发中，所以及时更新软件就显得极为重要，在软件侧边栏的 <code>设置</code> 中找到 <code>检查更新</code> 的字样，选择 <code>release</code> 当有更新是会显示，进行安装即可</p>',7)])])}const u=t(n,[["render",e]]);export{h as __pageData,u as default};
